"""Primary-candidate data for Layer One prospect scoring.

Every field comes from the research notes in
research_notes/Indian design system prospects/ (verify_*.md files take precedence).
Sub-scores: fin (0-25), org (0-20), acc (0-30), ds (0-25). See build_prospects.py
for the rubric. `missing=True` marks records where fin or org was scored
conservatively because data was not found.
"""

NONE_DS = "None found publicly (GitHub/Storybook not fully checkable)"
NONE_TEAM = "None found in this pass (careers pages mostly JS/ATS-rendered; not evidence of absence)"
ND = "Not publicly disclosed"


